<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { mountChartMotion, type ChartMotion } from './chart-motion'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),root=ref<HTMLElement|null>(null)
let motion:ChartMotion|undefined
onMounted(()=>{if(root.value)motion=mountChartMotion(root.value,'.tmusage-card')})
watch([dataset,state],async()=>{await nextTick();motion?.refresh()})
onBeforeUnmount(()=>motion?.destroy())
const labels=['Storage','Compute','Network','Cache'],groups=['Platform','Delivery'],colors=['#6366f1','#0d9488','#c2410c','#a855f7']
const values=computed(()=>dataset.value==='A'?[45,30,15,10]:dataset.value==='B'?[20,20,40,120]:dataset.value==='single'?[0,100,0,0]:[0,0,0,0])
const total=computed(()=>values.value.reduce((a,b)=>a+b,0))
const parents=computed(()=>[values.value[0]+values.value[1],values.value[2]+values.value[3]])
const tiles=computed(()=>values.value.map((value,i)=>{const g=Math.floor(i/2),parent=parents.value[g],w=total.value?280*parent/total.value:0,h=parent?180*value/parent:0;return{value,g,x:20+(g&&total.value?280*parents.value[0]/total.value:0),y:25+(i%2&&parent?180*values.value[i-1]/parent:0),w,h}}))
function reset(){dataset.value='A';state.value='ready';selected.value=0}
</script>
<template>
<section ref="root" class="tmusage-demo" aria-label="Local treemap example"><p>Synthetic resource units. Platform contains Storage/Compute; Delivery contains Network/Cache. Tile area is share of the whole, not two independent dimensions. Selection never filters the total.</p><div class="tmusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="single">One nonzero</option><option value="zero">All zero</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><div class="tmusage-card"><template v-if="state==='ready'"><p>Total: {{ total }} units. Platform {{ parents[0] }}; Delivery {{ parents[1] }}.</p><svg viewBox="0 0 320 230" role="img" aria-label="Two parent columns, each partitioned into its two children. Exact units and shares below."><rect class="tmusage-frame" x="20" y="25" width="280" height="180"/><template v-for="(tile,i) in tiles" :key="i"><rect v-if="tile.value>0" class="tmusage-tile" :class="{selected:selected===i}" :x="tile.x" :y="tile.y" :width="tile.w" :height="tile.h" :fill="colors[i]" :data-index="i" data-cm="fade"/><text v-if="tile.value>0&&tile.w>=62&&tile.h>=38" :x="tile.x+6" :y="tile.y+18" class="tmusage-label">{{ labels[i] }}</text></template><line v-if="parents[0]>0&&parents[1]>0" class="tmusage-divider" :x1="20+280*parents[0]/total" :x2="20+280*parents[0]/total" y1="25" y2="205"/><text v-if="!total" x="160" y="115" text-anchor="middle">No positive total: no tiles</text><text x="160" y="222" text-anchor="middle">{{ total?'Area = units / whole total · exact values below':'Shares are undefined at total zero' }}</text></svg><div role="group" aria-label="Select resource" class="tmusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @focus="selected=i" @click="selected=i"><span :style="{background:colors[i]}" aria-hidden="true"></span>{{ label }}</button></div><p role="status">{{ groups[Math.floor(selected/2)] }} / {{ labels[selected] }}: {{ values[selected] }} units; {{ total?(100*values[selected]/total).toFixed(1)+'% of whole':'whole share undefined' }}; {{ parents[Math.floor(selected/2)]?(100*values[selected]/parents[Math.floor(selected/2)]).toFixed(1)+'% of parent':'parent share undefined' }}.</p><table class="tmusage-data"><caption>Exact leaf units and shares, dataset {{ dataset }}</caption><thead><tr><th scope="col">Leaf</th><th scope="col">Units</th><th scope="col">Whole</th><th scope="col">Parent</th></tr></thead><tbody><tr v-for="(tile,i) in tiles" :key="i"><th scope="row">{{ labels[i] }}</th><td>{{ tile.value }}</td><td>{{ total?(100*tile.value/total).toFixed(1)+'%':'N/A' }}</td><td>{{ parents[tile.g]?(100*tile.value/parents[tile.g]).toFixed(1)+'%':'N/A' }}</td></tr></tbody></table><p class="tmusage-key">Parent membership: Storage/Compute → Platform; Network/Cache → Delivery. N/A means undefined, not zero. Small tiles omit chart text but remain in controls/table.</p></template><p v-else role="status" class="tmusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values and tiles are withheld.':'No resource records in this demonstration state. Choose Ready to recover.' }}</p></div></section>
</template>
<style scoped>

.tmusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.tmusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.tmusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.tmusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.tmusage-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.tmusage-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.tmusage-demo svg{display:block;width:100%;height:auto;max-height:320px;margin:16px 0}.tmusage-demo svg text{fill:var(--vp-c-text-2);font-size:11px}.tmusage-demo .tmusage-total{fill:var(--vp-c-text-1);font-size:24px;font-weight:700}.tmusage-choices{display:flex;gap:6px;flex-wrap:wrap}.tmusage-choices button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.tmusage-choices span{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}.tmusage-data{display:table!important;width:100%;font-size:12px}.tmusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.tmusage-data :is(td,th){padding:6px!important}.tmusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}

.tmusage-frame{fill:var(--vp-c-bg-soft);stroke:var(--vp-c-divider)}.tmusage-tile{stroke:var(--vp-c-bg);stroke-width:1;opacity:.8}.tmusage-tile.selected{opacity:1;stroke:var(--vp-c-text-1);stroke-width:2}.tmusage-demo svg .tmusage-label{fill:#fff;font-size:11px;font-weight:650;pointer-events:none}.tmusage-divider{stroke:var(--vp-c-text-1);stroke-width:2;stroke-dasharray:4 3;pointer-events:none}.tmusage-key{font-size:12px;color:var(--vp-c-text-2)}
</style>
